    private static List<(string E, string N)>[]? parsed;

    /// <summary>Entries (emoji, lowercase keywords) of category i.</summary>
    public static List<(string E, string N)> Entries(int i)
    {
        parsed ??= new List<(string, string)>[Categories.Length];
        if (parsed[i] != null) return parsed[i];
        var list = new List<(string, string)>();
        foreach (var part in Categories[i].Raw.Split(';'))
        {
            int sp = part.IndexOf(' '); if (sp <= 0) continue;
            list.Add((part[..sp], part[(sp + 1)..].ToLowerInvariant()));
        }
        return parsed[i] = list;
    }

    /// <summary>All emoji matching every whitespace-separated token of the query (in the keywords) or equal to it.</summary>
    public static List<(string E, string N)> Search(string query, int cap)
    {
        var res = new List<(string, string)>(); var tokens = query.ToLowerInvariant().Split(' ', StringSplitOptions.RemoveEmptyEntries); if (tokens.Length == 0) return res;
        for (int c = 0; c < Categories.Length && res.Count < cap; c++)
            foreach (var (e, n) in Entries(c))
            {
                bool ok = e == query.Trim(); if (!ok) { ok = true; foreach (var t in tokens) if (!n.Contains(t)) { ok = false; break; } }
                if (ok) { res.Add((e, n)); if (res.Count >= cap) break; }
            }
        return res;
    }
